      'Dan-D Pak POS application is committed to protecting user privacy information. Below is the detailed data collection and processing policy:',
  'Ứng dụng chưa được cấp quyền camera.\\nVào Settings → Ứng dụng → cấp quyền Camera rồi thử lại.':
      'The application has not been granted camera permissions.\\nGo to Settings → Applications → grant Camera permissions and try again.',
  '— Khác': '— Other',
  '— Mua chợ / nhập tên tay —': '— Buy from the market / enter name manually —',
  '• Camera: Ứng dụng chỉ sử dụng Camera để quét mã vạch/QR của sản phẩm phục vụ nghiệp vụ bán hàng (Retail) và nhập xuất kho (Warehouse). Chúng tôi cam kết KHÔNG lưu trữ hình ảnh, KHÔNG thu thập dữ liệu cá nhân hay gửi bất cứ hình ảnh/video nào từ camera lên máy chủ bên ngoài. Mọi quá trình xử lý hình ảnh mã vạch đều được diễn ra hoàn toàn cục bộ trên thiết bị của bạn thông qua Google ML Kit SDK.\\n':
      '• Camera: The application only uses the Camera to scan the barcode/QR of the product for retail and warehouse operations. We commit to NOT store images, collect personal data or send any images/videos from cameras to external servers. All barcode image processing takes place entirely locally on your device via the Google ML Kit SDK.\\n',
  '• Chúng tôi tuyệt đối không mua bán, trao đổi hoặc tiết lộ bất kỳ thông tin nào từ ứng dụng này cho bên thứ ba ngoại trừ trường hợp có yêu cầu chính thức từ cơ quan pháp luật có thẩm quyền.':
      '• We absolutely do not buy, sell, exchange or disclose any information from this application to third parties except in case of official request from a competent legal agency.',
  '• Chỉ sử dụng camera để nhận diện mã vạch tại chỗ.\\n':
      '• Only use the camera to identify barcodes on the spot.\\n',
  '• KHÔNG chụp ảnh, quay video hay lưu trữ dữ liệu của bạn.\\n':
      '• DO NOT take photos, record videos or store your data.\\n',
  '• KHÔNG truyền tải bất kỳ dữ liệu hình ảnh nào ra máy chủ bên ngoài.\\n\\n':
      '• DO NOT transmit any image data to an external server.\\n\\n',
  '• Mục đích sử dụng: Sử dụng duy nhất cho chức năng quét mã vạch sản phẩm (Retail) và nhập xuất kho (Warehouse) qua camera trên tablet/điện thoại.\\n':
      '• Intended use: Only used for scanning product barcodes (Retail) and importing and exporting warehouse (Warehouse) via camera on tablet/phone.\\n',
  '• Mục đích sử dụng: Đảm bảo giao tiếp thời gian thực (realtime) qua Socket.IO và gửi các yêu cầu nghiệp vụ (tạo hóa đơn, cập nhật bàn, gọi món) tới máy chủ POS trung tâm.\\n':
      '• Intended use: Ensure real-time communication via Socket.IO and send business requests (invoice creation, table updates, ordering) to the central POS server.\\n',
  '• Printternet & Network nội bộ (Local Network): Cần mạng để kết nối, truyền tải dữ liệu và đồng bộ hóa trạng thái đơn hàng thời gian thực giữa máy khách POS và máy chủ POS trung tâm (cục bộ hoặc Cloud/VPS).':
      '• Printernet & Internal Network (Local Network): Need network to connect, transmit data and synchronize real-time order status between POS client and central POS server (local or Cloud/VPS).',
  '• Security tuyệt đối: Mọi quá trình xử lý hình ảnh để nhận diện mã vạch đều được thực hiện cục bộ trên thiết bị của bạn thông qua thư viện Google ML Kit SDK. Ứng dụng KHÔNG chụp ảnh, KHÔNG ghi video, KHÔNG lưu trữ và KHÔNG gửi bất kỳ hình ảnh nào từ camera của bạn lên mạng hay máy chủ bên thứ ba.':
      '• Absolute security: All image processing for barcode recognition is performed locally on your device through the Google ML Kit SDK library. The app DOES NOT take photos, DOES NOT record video, DOES NOT store and DOES NOT send any images from your camera to the network or third party servers.',
  '• Security: Data giao dịch được mã hóa và truyền trực tiếp trong mạng nội bộ LAN cửa hàng hoặc qua kênh bảo mật VPS doanh nghiệp.':
      '• Security: Transaction data is encrypted and transmitted directly within the store\'s internal LAN or via the enterprise VPS security channel.',
  '• Tích chọn ô Đang sử dụng và Tự động in trên dòng máy in vừa thêm.\\n• Trong Menu FnB, gán đúng Station cho từng món ăn (chọn Bếp hoặc Bar). System sẽ tự động gửi món đến máy in tương ứng khi nhận đơn từ iPad hoặc POS quầy.\\n• Bấm nút [Save danh mục in] để hoàn tất cấu hình.':
      '• Check the boxes Currently in use and Automatically print on the newly added printer line.\\n• In the FnB Menu, assign the correct Station to each dish (choose Kitchen or Bar). The system will automatically send the order to the corresponding printer when receiving an order from an iPad or POS counter.\\n• Click the [Save print list] button to complete the configuration.',
  '• Ứng dụng Dan-D Pak POS hoạt động như một công cụ quản trị nguồn lực doanh nghiệp nội bộ. Chúng tôi KHÔNG thu thập thông tin cá nhân của khách hàng vãng lai sử dụng tablet tự phục vụ (Self-order) hay dữ liệu riêng tư của nhân viên ngoại trừ các thông tin đăng nhập nghiệp vụ (mã PIN nhân viên, thông tin chi nhánh cửa hàng) được lưu trữ an toàn trong vùng nhớ ứng dụng.':
      '• Dan-D Pak POS application acts as an internal business resource management tool. We DO NOT collect personal information from customers using self-service tablets or employees\' private data except for professional login information (employee PIN code, store branch information) that is securely stored in the application memory area.',
  '• Ứng dụng không tự động thu thập bất kỳ thông tin cá nhân hay vị trí địa lý của người dùng. Các thông tin cấu hình (URL máy chủ, mã PIN nhân viên, ca làm việc) được lưu trữ an toàn trong vùng nhớ cache bảo mật của ứng dụng trên thiết bị và chỉ được gửi tới máy chủ POS nội bộ được bạn cấu hình để phục vụ xác thực nghiệp vụ.':
      '• The application does not automatically collect any personal information or geographical location of users. Configuration information (server URL, employee PIN, shift) is safely stored in the application\'s secure cache on the device and is only sent to the internal POS server configured by you for business authentication.',
