  'Gợi ý': 'Suggested',
  'giảm': 'reduce',
  'Tồn': 'Stock',
  'Ứng dụng chưa được cấp quyền camera.\\nVào Cài đặt → Ứng dụng → cấp quyền Camera rồi thử lại.':
